/**
 * BC Core — shared layer for the Billy Crystal 860 site.
 *
 * Every component reads its content from one Google Sheets workbook. Core owns
 * that relationship so the component modules only deal with rendering:
 *
 *   - one batched request for all tabs, memoized for the page lifetime
 *   - rows normalized from positional arrays into keyed objects
 *   - shared escaping / URL / boolean helpers
 *   - setup-failure diagnostics that say what to actually go fix
 *
 * Public API (window.BC):
 *   BC.load()               -> Promise<{ [tab]: Row[] }>   warm/await the fetch
 *   BC.getSheet(tab)        -> Promise<Row[]>
 *   BC.getRow(tab, index=0) -> Promise<Row|null>           single-config tabs
 *   BC.esc(value)           -> HTML-escaped string
 *   BC.normalizeUrl(value)  -> href-safe string, or '' if unusable
 *   BC.isValidUrl(value)    -> boolean
 *   BC.bool(value)          -> boolean
 */
(() => {
  'use strict';

  const MODULE = '[BC Core]';

  const CONFIG = {
    spreadsheetId: '1vuJLzSrn-1lCG93ZPIV0qaQq_dMGwG6P0II9DDNOzGM',

    // Browser-visible by design. Restrict it to the Sheets API and to this
    // site's referrers in Google Cloud Console. See notes: the key plus the
    // spreadsheet ID grants read access to EVERY tab in the workbook, so the
    // workbook must contain nothing private.
    apiKey: 'AIzaSyB2bGN781PqOayJLrn1BDqsnWoPEy-A66A',

    // Tab name -> only the columns that tab actually uses. Keep these tight;
    // A:Z fetches 26 columns to use five.
    ranges: {
      Header: 'A:D',
      Calendar: 'A:E',
      FAQs: 'A:B',
    },

    // Set false before pinning the launch commit.
    debug: false,
  };

  const log = (...args) => {
    if (CONFIG.debug) console.log(MODULE, ...args);
  };

  const warn = (...args) => console.warn(MODULE, ...args);

  /* ------------------------------------------------------------------ *
   * Helpers
   * ------------------------------------------------------------------ */

  const ESCAPES = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  };

  /**
   * Escape a Sheet value for insertion into generated HTML. The client can
   * type anything into a cell, so every interpolated value goes through this.
   */
  const esc = value =>
    String(value ?? '').replace(/[&<>"']/g, ch => ESCAPES[ch]);

  const HOSTNAME_LIKE = /^[a-z0-9-]+(\.[a-z0-9-]+)+([/?#]|$)/i;

  /**
   * Turn a Sheet cell into a string that is safe to put in an href, or '' if
   * it cannot be one.
   *
   * Anchors (#tickets) and site paths (/tickets) are returned as authored.
   * A bare hostname gets https:// — clients type "telecharge.com/860"
   * constantly, and resolving that against the page would silently produce
   * billycrystal860.com/telecharge.com/860. The protocol check still rejects
   * javascript: and data:.
   */
  const normalizeUrl = value => {
    const raw = String(value ?? '').trim();
    if (!raw) return '';

    // Anything that isn't an anchor, a path, an explicit http(s) URL, or a
    // hostname is not a link — "TBD" must not resolve to a page on this site.
    const linkable =
      /^[#/]/.test(raw) || /^https?:\/\//i.test(raw) || HOSTNAME_LIKE.test(raw);

    if (!linkable) return '';

    const candidate = HOSTNAME_LIKE.test(raw) ? `https://${raw}` : raw;

    try {
      const url = new URL(candidate, window.location.href);

      if (url.protocol !== 'http:' && url.protocol !== 'https:') return '';

      return /^[#/]/.test(candidate) ? candidate : url.href;
    } catch {
      return '';
    }
  };

  const isValidUrl = value => normalizeUrl(value) !== '';

  const TRUTHY = new Set(['true', 'yes', 'y', 'x', '1', '✓', 'checked']);

  /** Tolerant flag reader for columns like MAT BEST AVAILABLE. */
  const bool = value => TRUTHY.has(String(value ?? '').trim().toLowerCase());

  /** "MAT BEST AVAILABLE" -> "matBestAvailable" */
  const camelKey = heading =>
    String(heading ?? '')
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+(.)?/g, (_, ch) => (ch ? ch.toUpperCase() : ''));

  /**
   * Sheets returns positional arrays. Keying rows by their heading means a
   * client inserting a column doesn't silently shift every field by one.
   */
  const toObjects = values => {
    if (!Array.isArray(values) || values.length < 2) return [];

    const keys = values[0].map(camelKey);

    return values
      .slice(1)
      .map(row => {
        const obj = {};

        keys.forEach((key, i) => {
          if (key) obj[key] = String(row[i] ?? '').trim();
        });

        return obj;
      })
      .filter(obj => Object.values(obj).some(Boolean));
  };

  /* ------------------------------------------------------------------ *
   * Fetch
   * ------------------------------------------------------------------ */

  const buildUrl = () => {
    const params = new URLSearchParams();

    Object.entries(CONFIG.ranges).forEach(([tab, columns]) => {
      params.append('ranges', `${tab}!${columns}`);
    });

    params.set('majorDimension', 'ROWS');
    params.set('valueRenderOption', 'FORMATTED_VALUE');
    params.set('key', CONFIG.apiKey);

    return (
      'https://sheets.googleapis.com/v4/spreadsheets/' +
      `${encodeURIComponent(CONFIG.spreadsheetId)}/values:batchGet?${params}`
    );
  };

  const diagnose = status => {
    switch (status) {
      case 400:
        return 'A tab name in CONFIG.ranges does not match the workbook exactly.';
      case 403:
        return 'Either the API key restrictions block this referrer, or the ' +
          'workbook is not shared. An API key cannot read a private sheet — ' +
          'set it to "Anyone with the link -> Viewer".';
      case 404:
        return 'CONFIG.spreadsheetId does not resolve.';
      case 429:
        return 'Google Sheets read quota exceeded.';
      default:
        return '';
    }
  };

  const fetchAll = async () => {
    const response = await fetch(buildUrl(), { credentials: 'omit' });

    if (!response.ok) {
      const hint = diagnose(response.status);
      throw new Error(
        `Google Sheets request failed: ${response.status}.${hint ? ` ${hint}` : ''}`
      );
    }

    const data = await response.json();
    const sheets = {};

    (data.valueRanges || []).forEach(entry => {
      // Ranges come back as "Calendar!A1:E99", quoted if the tab has spaces.
      const tab = String(entry.range || '')
        .split('!')[0]
        .replace(/^'|'$/g, '');

      if (tab) sheets[tab] = toObjects(entry.values || []);
    });

    return sheets;
  };

  // Memoized: every component awaits the same single request. A failure stays
  // failed for the page lifetime rather than having each module retry.
  let pending = null;

  const load = () => {
    if (!pending) {
      pending = fetchAll();

      // Two arguments, not .then().catch(): a success-only .then() would spawn
      // a derived promise whose rejection nobody owns, and the browser reports
      // that as an uncaught error on top of the ones callers already handle.
      pending.then(
        sheets => log('Loaded tabs:', Object.keys(sheets).join(', ')),
        () => {}
      );
    }

    return pending;
  };

  const getSheet = async tab => {
    const sheets = await load();

    if (!(tab in sheets)) {
      warn(`Tab "${tab}" was not returned. Add it to CONFIG.ranges.`);
      return [];
    }

    return sheets[tab];
  };

  const getRow = async (tab, index = 0) => {
    const rows = await getSheet(tab);
    return rows[index] || null;
  };

  window.BC = {
    config: CONFIG,
    load,
    getSheet,
    getRow,
    esc,
    normalizeUrl,
    isValidUrl,
    bool,
  };
})();
/**
 * BC Header — custom one-page header and navigation.
 *
 * The header BAR ships as static markup in Squarespace Code Injection so it
 * paints with the page: no fetch, no layout shift, and a working Get Tickets
 * link even if JavaScript or the Sheets request fails.
 *
 * This module then:
 *   - builds the nav panel (closed by default, so it costs no layout shift)
 *   - wires the menu: Escape, click-outside, focus trap, scroll lock
 *   - publishes --bc-header-height so anchors clear the fixed bar
 *   - replaces the center text and ticket button from the Header sheet tab
 *
 * Nothing here is required for the header to be usable. It only enhances.
 */
(() => {
  'use strict';

  const MODULE = '[BC Header]';
  const SELECTOR = '.bc-header';
  const TAB = 'Header';

  // Same-page anchors. These live here rather than in the Squarespace
  // injection so nav changes are a git commit, not a CMS edit.
  const NAV = [
    { label: 'About', href: '#about' },
    { label: 'Calendar', href: '#calendar' },
    { label: 'Tickets', href: '#tickets' },
    { label: 'Creative Team', href: '#creative' },
    { label: 'FAQ', href: '#faq' },
  ];

  const FOCUSABLE = 'a[href], button:not([disabled])';
  const PANEL_ID = 'bc-header-panel';

  let header = null;
  let toggle = null;
  let panel = null;
  let lastFocus = null;

  /* ------------------------------------------------------------------ *
   * Menu
   * ------------------------------------------------------------------ */

  /**
   * Only offer nav items whose section is actually on the page. The site grows
   * a section at a time, and a link to a section that does not exist is a dead
   * link the visitor can click. Items reappear on their own once the matching
   * id shows up, so NAV stays the single list to maintain.
   */
  const availableNav = () => {
    const present = NAV.filter(item => document.getElementById(item.href.slice(1)));

    if (BC.config.debug && present.length !== NAV.length) {
      const missing = NAV.filter(item => !present.includes(item)).map(item => item.href);
      console.warn(
        `${MODULE} Nav items hidden, no matching section on the page:`,
        missing.join(', ')
      );
    }

    return present;
  };

  const buildPanel = () => {
    const nav = document.createElement('nav');

    nav.className = 'bc-header__panel';
    nav.id = PANEL_ID;
    nav.hidden = true;
    nav.setAttribute('aria-label', 'Main');

    const items = availableNav().map(
      item => `
        <li class="bc-header__nav-item">
          <a class="bc-header__link" href="${BC.esc(item.href)}">
            ${BC.esc(item.label)}
          </a>
        </li>
      `
    ).join('');

    nav.innerHTML = `<ul class="bc-header__nav">${items}</ul>`;

    return nav;
  };

  const isOpen = () => toggle.getAttribute('aria-expanded') === 'true';

  const setOpen = open => {
    toggle.setAttribute('aria-expanded', String(open));
    toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');

    panel.hidden = !open;
    document.documentElement.classList.toggle('bc-menu-open', open);

    if (open) {
      lastFocus = document.activeElement;
      const first = panel.querySelector(FOCUSABLE);
      if (first) first.focus();
    } else if (lastFocus) {
      lastFocus.focus();
      lastFocus = null;
    }
  };

  /** Keep Tab inside the open menu; include the toggle so it stays reachable. */
  const trapFocus = event => {
    const items = [toggle, ...panel.querySelectorAll(FOCUSABLE)];
    if (!items.length) return;

    const first = items[0];
    const last = items[items.length - 1];

    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  };

  const bindMenu = () => {
    toggle.addEventListener('click', () => setOpen(!isOpen()));

    document.addEventListener('keydown', event => {
      if (!isOpen()) return;

      if (event.key === 'Escape') {
        setOpen(false);
      } else if (event.key === 'Tab') {
        trapFocus(event);
      }
    });

    // Clicking anywhere outside the header closes the menu.
    document.addEventListener('click', event => {
      if (isOpen() && !header.contains(event.target)) setOpen(false);
    });
  };

  /* ------------------------------------------------------------------ *
   * Anchors
   * ------------------------------------------------------------------ */

  const prefersReducedMotion = () =>
    window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /**
   * Scroll to a section without writing #id into the address bar.
   *
   * The default anchor behaviour appends the fragment and pushes a history
   * entry; scrolling by hand keeps the URL clean. scroll-margin-top on the
   * target still keeps it clear of the sticky bar.
   *
   * Returns false when there is nothing to scroll to, so the caller can let
   * the browser handle it normally.
   */
  const scrollToTarget = href => {
    const id = (href || '').slice(1);
    const target = id && document.getElementById(id);

    if (!target) return false;

    target.scrollIntoView({
      behavior: prefersReducedMotion() ? 'auto' : 'smooth',
      block: 'start',
    });

    // Move keyboard and screen-reader users along with the visual jump.
    if (!target.hasAttribute('tabindex')) {
      target.setAttribute('tabindex', '-1');
    }

    target.focus({ preventScroll: true });

    return true;
  };

  const bindAnchors = () => {
    header.addEventListener('click', event => {
      const link = event.target.closest('a[href^="#"]');

      if (!link || !header.contains(link)) return;

      // Always prevent, never conditionally. A bare "#", or a link whose
      // section has not been built yet, would otherwise fall through to the
      // browser and write the fragment into the address bar.
      event.preventDefault();

      // Close first: setOpen(false) restores focus to the toggle, which would
      // otherwise undo the focus move onto the target section.
      if (toggle && isOpen()) setOpen(false);

      scrollToTarget(link.getAttribute('href'));
    });
  };

  /* ------------------------------------------------------------------ *
   * Layout
   * ------------------------------------------------------------------ */

  /** Anchor targets use this as scroll-margin-top so the bar never covers them. */
  const measure = () => {
    document.documentElement.style.setProperty(
      '--bc-header-height',
      `${header.offsetHeight}px`
    );
  };

  /**
   * position: sticky fails silently when any ancestor establishes a scroll
   * container. Squarespace templates set overflow-x on wrappers often enough
   * that this is worth catching locally rather than on the live site.
   *
   * overflow: clip is fine — it does not create a scroll container.
   */
  const warnIfStickyBroken = () => {
    if (!BC.config.debug) return;
    if (getComputedStyle(header).position !== 'sticky') return;

    for (let node = header.parentElement; node; node = node.parentElement) {
      const style = getComputedStyle(node);
      const values = [style.overflow, style.overflowX, style.overflowY];

      if (values.some(value => value && !['visible', 'clip'].includes(value))) {
        console.warn(
          `${MODULE} position: sticky is being blocked by an ancestor with ` +
            `overflow ${style.overflowX}/${style.overflowY}.`,
          node
        );
        return;
      }
    }
  };

  const bindMeasure = () => {
    measure();

    let frame = null;

    window.addEventListener('resize', () => {
      if (frame) cancelAnimationFrame(frame);
      frame = requestAnimationFrame(measure);
    });

    // Webfonts can change the bar height after first paint.
    if (document.fonts?.ready) document.fonts.ready.then(measure);
  };

  /* ------------------------------------------------------------------ *
   * Sheet content
   * ------------------------------------------------------------------ */

  const applyCenterText = text => {
    const center = header.querySelector('.bc-header__cta');
    if (!center) return;

    center.textContent = text;
    center.hidden = !text;
  };

  const applyButton = ({ buttonText, buttonUrl, buttonTarget }) => {
    const button = header.querySelector('.bc-header__tickets');
    if (!button) return;

    // A row exists and the client cleared the fields — that is a deliberate
    // "hide the button", so honour it. A missing row or failed fetch is not,
    // and is handled by leaving the markup fallback alone (see init).
    // Either field blanked is a deliberate "no button" per the sheet spec.
    if (!buttonText.trim() || !buttonUrl.trim()) {
      button.hidden = true;
      return;
    }

    // Normalized, not raw: a bare hostname in the cell must not become a
    // path on this site.
    const url = BC.normalizeUrl(buttonUrl);

    // Filled in but unusable is a typo, not an intent — keep the markup
    // fallback rather than removing the site's primary call to action.
    if (!url) {
      console.warn(
        `${MODULE} BUTTON URL is not a usable link, keeping the markup ` +
          'default:',
        buttonUrl
      );
      return;
    }

    // "#" is a placeholder the sheet is entitled to hold. It is applied as
    // authored — bindAnchors keeps it out of the address bar — but say so
    // while debugging, so it cannot ship unnoticed.
    if (url === '#' && BC.config.debug) {
      console.warn(
        `${MODULE} BUTTON URL is still the placeholder "#" — the ticket ` +
          'button will not go anywhere.'
      );
    }

    button.textContent = buttonText;
    button.href = url;
    button.hidden = false;

    if (buttonTarget.trim().toLowerCase() === 'blank') {
      button.target = '_blank';
      button.rel = 'noopener noreferrer';
    } else {
      button.removeAttribute('target');
      button.removeAttribute('rel');
    }
  };

  /* ------------------------------------------------------------------ *
   * Init
   * ------------------------------------------------------------------ */

  const init = async () => {
    header = document.querySelector(SELECTOR);

    if (!header) {
      console.warn(
        `${MODULE} No ${SELECTOR} found. Add the header markup to ` +
          'Squarespace Code Injection -> Header.'
      );
      return;
    }

    if (!window.BC) return;

    toggle = header.querySelector('.bc-header__menu');

    if (toggle) {
      panel = buildPanel();
      header.appendChild(panel);

      toggle.setAttribute('aria-controls', PANEL_ID);
      toggle.setAttribute('aria-expanded', 'false');

      bindMenu();
    }

    bindAnchors();
    bindMeasure();
    warnIfStickyBroken();

    // Everything above works offline. Only the copy below needs the network,
    // and the markup already renders a usable header without it.
    try {
      const row = await BC.getRow(TAB);

      if (!row) {
        console.warn(
          `${MODULE} The ${TAB} tab has no configuration row. ` +
            'Keeping the markup defaults.'
        );
        return;
      }

      applyCenterText(row.centerCallToAction || '');
      applyButton({
        buttonText: row.buttonText || '',
        buttonUrl: row.buttonUrl || '',
        buttonTarget: row.buttonTarget || '',
      });
    } catch (error) {
      // Deliberately non-fatal: the baked-in ticket link stays on screen.
      console.error(`${MODULE} Keeping markup defaults.`, error);
    }
  };

  window.BCHeader = { init };
})();
/**
 * BC Calendar — month grid of performances, each linking to Telecharge.
 *
 * Reads the Calendar tab through BC core, so it shares the one batched Sheets
 * request with every other module rather than fetching on its own — including
 * when the visitor pages between months, which costs no network at all.
 *
 * The sheet holds every date in the run, dark days included. A date only
 * becomes a performance when it has a time, so empty time cells simply render
 * as a dark day.
 */
(() => {
  'use strict';

  const MODULE = '[BC Calendar]';
  const SELECTOR = '#bc-calendar';
  const TAB = 'Calendar';

  const CONFIG = {
    baseUrl: 'https://www.telecharge.com/Billy-Crystal-860-Tickets',

    // Tracking id. Left empty for now — AID and utm_id are omitted from the
    // links entirely until it is filled in, rather than sent blank.
    aid: '',

    utm: {
      utm_source: 'show_site',
      utm_campaign: 'BillyCrystal860SS',
      utm_medium: 'web',
    },

    // Fallback month, used only when the sheet has no performances at all.
    startYear: 2026,
    startMonth: 9, // 0-based: October

    // Show the legend whenever ANY month in the sheet has a Best Available
    // ticked. Set true to narrow it to only the month currently on screen.
    legendPerMonth: false,

    legendText: 'Click on the date and time below for tickets. Best Availability =',

    // Below this width the month grid is replaced by a vertical list of dates.
    // Set to '' to keep the grid at every size (it tightens up under 900px).
    listBelow: '(max-width: 680px)',

    // Pad every month out to six rows. Keeps the block exactly the same height
    // month to month, at the cost of a trailing empty row in most months.
    fixedSixRows: false,
  };

  const MONTH_NAMES = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ];

  // Both forms ship in the markup and CSS picks one, so the switch happens on
  // resize with no listener and no re-render.
  const WEEKDAYS = [
    { full: 'Sunday', short: 'Sun' },
    { full: 'Monday', short: 'Mon' },
    { full: 'Tuesday', short: 'Tue' },
    { full: 'Wednesday', short: 'Wed' },
    { full: 'Thursday', short: 'Thu' },
    { full: 'Friday', short: 'Fri' },
    { full: 'Saturday', short: 'Sat' },
  ];

  const WEEK = 7;
  const SIX_ROWS = 42;

  let root = null;
  let media = null;
  let eventsByDate = {};
  let months = [];
  let index = 0;
  let bound = false;

  /* ------------------------------------------------------------------ *
   * Data
   * ------------------------------------------------------------------ */

  const pad = value => String(value).padStart(2, '0');

  const monthKey = (year, month) => `${year}-${pad(month + 1)}`;

  const dateKey = (year, month, day) => `${year}-${pad(month + 1)}-${pad(day)}`;

  const todayKey = () => {
    const now = new Date();
    return dateKey(now.getFullYear(), now.getMonth(), now.getDate());
  };

  /** The sheet's DATE column arrives formatted, e.g. "10/01/2026". */
  const toKey = value => {
    const [month, day, year] = String(value || '').split('/');
    if (!month || !day || !year) return '';
    return `${year}-${pad(month)}-${pad(day)}`;
  };

  const addPerformance = (list, time, flag, type) => {
    const label = String(time || '').trim();
    if (!label) return;

    list.push({
      label,
      // Telecharge wants the time with no space: "7:00PM".
      urlTime: label.replace(/\s+/g, ''),
      bestAvailable: BC.bool(flag),
      type,
    });
  };

  const buildEventMap = rows => {
    const map = {};

    rows.forEach(row => {
      const key = toKey(row.date);
      if (!key) return;

      const list = [];
      addPerformance(list, row.matineeTime, row.matBestAvailable, 'matinee');
      addPerformance(list, row.eveningTime, row.eveBestAvailable, 'evening');

      // Days without a time are dark days; they need no entry.
      if (list.length) map[key] = list;
    });

    return map;
  };

  const collectMonths = () =>
    [...new Set(Object.keys(eventsByDate).map(key => key.slice(0, 7)))].sort();

  /** Open on the current month if the run covers it, otherwise the next one. */
  const startingIndex = () => {
    if (!months.length) return 0;

    const now = new Date();
    const found = months.findIndex(key => key >= monthKey(now.getFullYear(), now.getMonth()));

    return found === -1 ? months.length - 1 : found;
  };

  const visibleMonth = () => {
    if (!months.length) {
      return { year: CONFIG.startYear, month: CONFIG.startMonth };
    }

    const [year, month] = months[index].split('-');
    return { year: Number(year), month: Number(month) - 1 };
  };

  /* ------------------------------------------------------------------ *
   * Links
   * ------------------------------------------------------------------ */

  /**
   * Built by hand rather than with URLSearchParams: Telecharge expects the
   * literal slashes and colon inside PerformanceDateTime, and URLSearchParams
   * would percent-encode them into %2F and %3A.
   */
  const ticketUrl = (key, performance) => {
    const [year, month, day] = key.split('-');
    const params = [`PerformanceDateTime=${month}/${day}/${year}%20${performance.urlTime}`];

    if (CONFIG.aid) params.push(`AID=${CONFIG.aid}`);

    Object.entries(CONFIG.utm).forEach(([name, value]) => {
      if (value) params.push(`${name}=${value}`);
    });

    if (CONFIG.aid) params.push(`utm_id=${CONFIG.aid}`);

    return `${CONFIG.baseUrl}?${params.join('&')}`;
  };

  const longDate = key => {
    const [year, month, day] = key.split('-').map(Number);
    return new Date(year, month - 1, day).toLocaleDateString('en-US', {
      weekday: 'long',
      month: 'long',
      day: 'numeric',
      year: 'numeric',
    });
  };

  /* ------------------------------------------------------------------ *
   * Rendering
   * ------------------------------------------------------------------ */

  const performanceHtml = (key, performance) => `
    <li class="bc-calendar__performance${performance.bestAvailable ? ' is-best-available' : ''}">
      <a
        class="bc-calendar__link"
        href="${BC.esc(ticketUrl(key, performance))}"
        target="_blank"
        rel="noopener noreferrer"
        aria-label="Buy tickets, ${BC.esc(longDate(key))} at ${BC.esc(performance.label)}"
      >${BC.esc(performance.label)}</a>
    </li>
  `;

  const dayHtml = (key, day, todayKey) => {
    const performances = eventsByDate[key] || [];

    const classes = ['bc-calendar__day'];
    if (!performances.length) classes.push('is-dark');
    if (key < todayKey) classes.push('is-past');
    if (key === todayKey) classes.push('is-today');

    return `
      <div class="${classes.join(' ')}">
        <time class="bc-calendar__date" datetime="${key}">${day}</time>
        ${
          performances.length
            ? `<ul class="bc-calendar__times">
                 ${performances.map(p => performanceHtml(key, p)).join('')}
               </ul>`
            : ''
        }
      </div>
    `;
  };

  const gridHtml = (year, month) => {
    const today = todayKey();
    const firstWeekday = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    const cells = WEEKDAYS.map(
      day => `
        <div class="bc-calendar__weekday" aria-hidden="true">
          <span class="bc-calendar__weekday-full">${day.full}</span>
          <span class="bc-calendar__weekday-short">${day.short}</span>
        </div>
      `
    );

    const days = [];

    for (let i = 0; i < firstWeekday; i += 1) {
      days.push('<div class="bc-calendar__day is-empty"></div>');
    }

    for (let day = 1; day <= daysInMonth; day += 1) {
      days.push(dayHtml(dateKey(year, month, day), day, today));
    }

    // Pad to whole weeks only. Padding every month to six rows leaves a dead
    // empty row in most of them — October needs exactly five. Counting day
    // cells rather than children keeps the weekday headers out of the maths.
    const target = CONFIG.fixedSixRows
      ? SIX_ROWS
      : Math.ceil(days.length / WEEK) * WEEK;

    while (days.length < target) {
      days.push('<div class="bc-calendar__day is-empty"></div>');
    }

    return cells.concat(days).join('');
  };

  /**
   * Mobile view. A seven-column grid at 375px gives roughly 50px columns —
   * too narrow for "7:00 PM" at a legible size, and shrinking it turns every
   * showtime into a sub-44px tap target. Listing the dates instead keeps the
   * links full width and, unlike a date-only grid, still lets a day carry both
   * its matinee and its evening as separate links.
   *
   * Reuses performanceHtml, so the links, tracking and Best Available marker
   * are the same objects the grid renders.
   */
  const listHtml = (year, month) => {
    const prefix = monthKey(year, month);
    const today = todayKey();

    const keys = Object.keys(eventsByDate)
      .filter(key => key.startsWith(prefix))
      .sort();

    if (!keys.length) {
      return '<p class="bc-calendar__empty">No performances this month.</p>';
    }

    const rows = keys.map(key => {
      const [year_, month_, day_] = key.split('-').map(Number);
      const date = new Date(year_, month_ - 1, day_);

      return `
        <li class="bc-calendar__list-day${key < today ? ' is-past' : ''}">
          <div class="bc-calendar__list-date">
            <span class="bc-calendar__list-weekday">
              ${date.toLocaleDateString('en-US', { weekday: 'short' })}
            </span>
            <time datetime="${key}">
              ${date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
            </time>
          </div>

          <ul class="bc-calendar__times">
            ${eventsByDate[key].map(p => performanceHtml(key, p)).join('')}
          </ul>
        </li>
      `;
    });

    return `<ol class="bc-calendar__list">${rows.join('')}</ol>`;
  };

  const useList = () => Boolean(CONFIG.listBelow) && Boolean(media && media.matches);

  const monthHasBestAvailable = (year, month) => {
    const prefix = monthKey(year, month);

    return Object.entries(eventsByDate).some(
      ([key, list]) => key.startsWith(prefix) && list.some(p => p.bestAvailable)
    );
  };

  const showLegend = (year, month) => {
    if (!CONFIG.legendPerMonth) {
      return Object.values(eventsByDate).some(list => list.some(p => p.bestAvailable));
    }

    return monthHasBestAvailable(year, month);
  };

  const render = () => {
    const { year, month } = visibleMonth();

    const hasPrev = index > 0;
    const hasNext = index < months.length - 1;

    root.innerHTML = `
      <div class="bc-calendar">

        <div class="bc-calendar__nav">
          <button
            class="bc-calendar__prev"
            type="button"
            aria-label="Previous month"
            ${hasPrev ? '' : 'disabled'}
          ></button>

          <h2 class="bc-calendar__month" aria-live="polite">
            ${MONTH_NAMES[month]}
          </h2>

          <button
            class="bc-calendar__next"
            type="button"
            aria-label="Next month"
            ${hasNext ? '' : 'disabled'}
          ></button>
        </div>

        <p class="bc-calendar__legend"${showLegend(year, month) ? '' : ' hidden'}>
          ${BC.esc(CONFIG.legendText)}
          <span class="bc-calendar__swatch" aria-hidden="true"></span>
          <span class="bc-calendar__sr">highlighted showtimes</span>
        </p>

        ${
          useList()
            ? listHtml(year, month)
            : `<div class="bc-calendar__grid">${gridHtml(year, month)}</div>`
        }

      </div>
    `;
  };

  /* ------------------------------------------------------------------ *
   * Interaction
   * ------------------------------------------------------------------ */

  const go = (step, selector) => {
    const next = index + step;
    if (next < 0 || next > months.length - 1) return;

    index = next;
    render();

    // The button was just replaced by the re-render. Put focus back on it so a
    // keyboard user can keep paging; fall back to the heading at either end.
    const button = root.querySelector(selector);

    if (button && !button.disabled) {
      button.focus();
    } else {
      root.querySelector('.bc-calendar__month')?.focus?.();
    }
  };

  const bindEvents = () => {
    if (bound) return;
    bound = true;

    // Delegated, so the listener survives every re-render.
    root.addEventListener('click', event => {
      if (event.target.closest('.bc-calendar__prev')) go(-1, '.bc-calendar__prev');
      if (event.target.closest('.bc-calendar__next')) go(1, '.bc-calendar__next');
    });
  };

  /* ------------------------------------------------------------------ *
   * Init
   * ------------------------------------------------------------------ */

  const init = async () => {
    root = document.querySelector(SELECTOR);

    if (!root || !window.BC) return;

    root.setAttribute('aria-busy', 'true');

    try {
      const rows = await BC.getSheet(TAB);

      eventsByDate = buildEventMap(rows);
      months = collectMonths();
      index = startingIndex();

      if (!months.length && BC.config.debug) {
        console.warn(
          `${MODULE} No performance times in the ${TAB} tab yet — showing ` +
            `${MONTH_NAMES[CONFIG.startMonth]} ${CONFIG.startYear} as an empty month.`
        );
      }

      if (CONFIG.listBelow && !media) {
        media = window.matchMedia(CONFIG.listBelow);
        // Re-render on the way across the breakpoint, in both directions.
        media.addEventListener('change', render);
      }

      render();
      bindEvents();
    } catch (error) {
      console.error(`${MODULE} Unable to load the calendar.`, error);
      root.hidden = true;
    } finally {
      root.removeAttribute('aria-busy');
      root.classList.remove('is-loading');
    }
  };

  window.BCCalendar = { init };
})();
/**
 * BC FAQ — accessible accordion built from the FAQs sheet tab.
 *
 * Row order in the sheet is display order. Questions are plain text.
 * Answers are escaped, then given back the two things clients actually use:
 * line breaks and links.
 */
(() => {
  'use strict';

  const MODULE = '[BC FAQ]';
  const SELECTOR = '#bc-faq';
  const TAB = 'FAQs';

  // Heading level for each question. Should sit one below the section's own
  // heading in the page outline.
  const HEADING = 'h3';

  // false = opening one answer closes the others.
  const ALLOW_MULTIPLE = true;

  const LINK = /((?:https?:\/\/|www\.)[^\s<]+[^\s<.,;:!?)])/gi;

  let bound = false;

  /* ------------------------------------------------------------------ *
   * Rendering
   * ------------------------------------------------------------------ */

  /**
   * Escape first, then re-introduce only what we chose to allow. Doing it in
   * this order means a cell containing markup is inert no matter what.
   */
  const linkify = html =>
    html.replace(
      LINK,
      match =>
        `<a href="${BC.normalizeUrl(match)}" target="_blank" rel="noopener noreferrer">${match}</a>`
    );

  const formatAnswer = value =>
    // Order matters: linkify LAST. Rewriting newlines after the anchors exist
    // injects <br> into the middle of the tags we just built.
    BC.esc(value)
      .split(/\n{2,}/)
      .map(block => `<p>${linkify(block.trim().replace(/\n/g, '<br>'))}</p>`)
      .join('');

  const renderItem = (row, index) => {
    const questionId = `bc-faq-q-${index}`;
    const answerId = `bc-faq-a-${index}`;

    return `
      <div class="bc-faq__item">

        <${HEADING} class="bc-faq__heading">
          <button
            class="bc-faq__question"
            type="button"
            id="${questionId}"
            aria-expanded="false"
            aria-controls="${answerId}"
          >
            <span class="bc-faq__label">${BC.esc(row.question)}</span>
            <span class="bc-faq__icon" aria-hidden="true"></span>
          </button>
        </${HEADING}>

        <div
          class="bc-faq__answer"
          id="${answerId}"
          role="region"
          aria-labelledby="${questionId}"
          hidden
        >
          <div class="bc-faq__answer-inner">
            ${formatAnswer(row.answer)}
          </div>
        </div>

      </div>
    `;
  };

  /* ------------------------------------------------------------------ *
   * Interaction
   * ------------------------------------------------------------------ */

  const setItemOpen = (button, open) => {
    const answer = document.getElementById(
      button.getAttribute('aria-controls')
    );

    if (!answer) return;

    button.setAttribute('aria-expanded', String(open));
    answer.hidden = !open;
  };

  const bindEvents = container => {
    // Delegated, so re-rendering the list never needs re-binding.
    if (bound) return;
    bound = true;

    container.addEventListener('click', event => {
      const button = event.target.closest('.bc-faq__question');
      if (!button) return;

      const open = button.getAttribute('aria-expanded') === 'true';

      if (!ALLOW_MULTIPLE && !open) {
        container
          .querySelectorAll('.bc-faq__question[aria-expanded="true"]')
          .forEach(other => setItemOpen(other, false));
      }

      setItemOpen(button, !open);
    });
  };

  /* ------------------------------------------------------------------ *
   * Init
   * ------------------------------------------------------------------ */

  const init = async () => {
    const container = document.querySelector(SELECTOR);

    if (!container || !window.BC) return;

    container.setAttribute('aria-busy', 'true');

    try {
      const rows = await BC.getSheet(TAB);
      const faqs = rows.filter(row => row.question && row.answer);

      if (!faqs.length) {
        // Nothing to show and nothing broken — leave no empty furniture.
        container.hidden = true;
        return;
      }

      container.innerHTML = faqs.map(renderItem).join('');
      bindEvents(container);
    } catch (error) {
      console.error(`${MODULE} Unable to load FAQs.`, error);
      container.hidden = true;
    } finally {
      container.removeAttribute('aria-busy');
      container.classList.remove('is-loading');
    }
  };

  window.BCFAQ = { init };
})();
/**
 * BC Main — entry point.
 *
 * Warms the batched Sheets request as soon as the bundle evaluates, then
 * initializes each component once the DOM is ready. Every module is isolated:
 * one failing component cannot stop the others from rendering.
 *
 * Source order in the bundle must be: core.js -> components -> main.js
 */
(() => {
  'use strict';

  const MODULE = '[BC]';

  // Global names, not bare identifiers — see start() below.
  const MODULES = ['BCHeader', 'BCCalendar', 'BCFAQ', 'BCCreative'];

  /**
   * Look modules up on `window` rather than referencing them directly.
   *
   *   BCHeader?.init?.()          // ReferenceError if BCHeader is undeclared
   *   window.BCHeader?.init?.()   // safe
   *
   * Optional chaining guards null/undefined *values*, not undeclared
   * identifiers. A bare reference to a module that was dropped from the
   * bundle throws and takes down every module after it in this loop.
   */
  const start = name => {
    const mod = window[name];

    if (!mod || typeof mod.init !== 'function') return;

    try {
      const result = mod.init();

      // init() is async — a rejection surfaces here, not in the catch below.
      if (result && typeof result.catch === 'function') {
        result.catch(error =>
          console.error(`${MODULE} ${name} failed while loading.`, error)
        );
      }
    } catch (error) {
      console.error(`${MODULE} ${name} failed to initialize.`, error);
    }
  };

  const init = () => {
    if (!window.BC) {
      console.error(
        `${MODULE} Core did not load — no components will render. ` +
          'Check the bundle order (core.js must come first).'
      );
      return;
    }

    MODULES.forEach(start);

    if (window.BC.config?.debug) console.log(`${MODULE} Site initialized.`);
  };

  // Kick the fetch off now so it overlaps with the rest of DOM parsing rather
  // than starting at DOMContentLoaded. Components await the same promise;
  // this catch only keeps the warm-up from logging an unhandled rejection.
  window.BC?.load?.().catch(() => {});

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init, { once: true });
  } else {
    init();
  }
})();
